from pathlib import Path
import pandas as pd,numpy as np,json
O=Path('outputs');W=Path('work');d=pd.read_csv(W/'stage6_rbm6_gtex_direct_input.csv');n=pd.read_csv(O/'stage6_rbm6_gtex_direct_nfe_variant_index.csv');d=d.merge(n[['rs','gnomad_index','gnomad_af_alt','sign_to_anchor']],on='rs',validate='one_to_one');d['nfe_idx']=d.gnomad_index;d['nfe_sign']=d.sign_to_anchor;d['nfe_anchor_af']=np.where(d.nfe_sign==1,d.gnomad_af_alt,1-d.gnomad_af_alt);d['qtl_af']=d.ac/d.an;d['qtl_diff']=abs(d.qtl_af-d.nfe_anchor_af);d['fi_diff']=abs(d.Mak_FI_af-d.nfe_anchor_af);pre=len(d);d=d[d.qtl_diff.le(.2)&d.fi_diff.le(.2)].sort_values('position').copy();assert np.isfinite(d[['beta','se','Mak_FI_beta','Mak_FI_se','Ye_FFS_beta','Ye_FFS_se']]).all().all();d.to_csv(O/'stage6_rbm6_gtex_direct_aligned.csv',index=False);pub=pd.read_csv(O/'stage6_rbm6_gtex_cortex_published_cs_coverage.tsv',sep='\t').drop_duplicates(['cs_id','variant']);m=pub[pub.variant.isin(set(d.variant))];receipt={'input_reference_matched':pre,'retained':len(d),'excluded':pre-len(d),'mean_qtl_af_difference':float(d.qtl_diff.mean()),'max_qtl_af_difference':float(d.qtl_diff.max()),'mean_fi_af_difference':float(d.fi_diff.mean()),'max_fi_af_difference':float(d.fi_diff.max()),'ffs_af_available_count':int(d.Ye_FFS_af.notna().sum()),'top_present':bool(d.variant.eq('chr3_50085532_T_C').any()),'published_set_unique':len(pub),'published_set_matched':len(m),'published_set_matched_pip_sum':float(m.pip.sum()),'published_set_total_pip_sum':float(pub.pip.sum())};(O/'stage6_rbm6_gtex_direct_align_receipt.json').write_text(json.dumps(receipt,indent=2)+'\n');print(receipt,flush=True)
